Rules.InvariantScript:
Set(gblBusy, true);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
UpdateContext({locClusterPage: 1, locRejectId: Blank()});
Select(btnDoLoadClusters);
Set(gblBusy, false)

IfError(
    ClearCollect(
        colClusters,
        Filter(
        db_dq_sandbox.dquspGetClusterList(
            {
                ActorUpn: gblActorUpn,
                DomainCode: Blank(),
                StatusGroup: "OPEN",
                Page: locClusterPage,
                PageSize: 25
            }
        ).ResultSets.Table1,
            !IsBlank(ClusterId)
        )
    ),
    Set(gblError, {IsVisible: true, Title: "Could not load clusters", Detail: FirstError.Message})
)

Navigate(
    scrQueue,
    ScreenTransition.None,
    {locInAssignee: "", locInSeverity: "", locInOverdue: false, locInCluster: Blank()}
)

Set(gblBusy, true);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
IfError(
    Set(
        gblWriteResult,
        First(
            db_dq_sandbox.dquspConfirmCluster(
                {
                    ActorUpn: gblActorUpn,
                    ClusterId: ThisItem.ClusterId,
                    Confirm: true,
                    Comment: ""
                }
            ).ResultSets.Table1
        )
    ),
    Set(gblError, {IsVisible: true, Title: "Could not confirm the cluster", Detail: FirstError.Message})
);
If(
    Upper(Coalesce(gblWriteResult.Outcome, "")) = "OK",
    Notify("Grouping confirmed. No exception has been disposed of.", NotificationType.Success, 4000),
    Notify(Coalesce(gblWriteResult.Message, "The cluster was not confirmed."), NotificationType.Error, 6000)
);
Set(gblBusy, false);
Select(btnDoLoadClusters)

Navigate(
    scrQueue,
    ScreenTransition.None,
    {
        locInAssignee: "",
        locInSeverity: "",
        locInOverdue: false,
        locInCluster: ThisItem.ClusterId
    }
)

Set(gblBusy, true);
Set(gblError, {IsVisible: false, Title: "", Detail: ""});
IfError(
    Set(
        gblWriteResult,
        First(
            db_dq_sandbox.dquspConfirmCluster(
                {
                    ActorUpn: gblActorUpn,
                    ClusterId: locRejectId,
                    Confirm: false,
                    Comment: Trim(txtRejectReasonCL.Text)
                }
            ).ResultSets.Table1
        )
    ),
    Set(gblError, {IsVisible: true, Title: "Could not reject the cluster", Detail: FirstError.Message})
);
If(
    Upper(Coalesce(gblWriteResult.Outcome, "")) = "OK",
    Notify("Grouping rejected. That feedback improves the grouping.", NotificationType.Success, 4000),
    Notify(Coalesce(gblWriteResult.Message, "The cluster was not rejected."), NotificationType.Error, 6000)
);
UpdateContext({locRejectId: Blank()});
Reset(txtRejectReasonCL);
Set(gblBusy, false);
Select(btnDoLoadClusters)
